ALTER TABLE "Address" ADD COLUMN "location_confirmed" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE neighborhood_references (
 id UUID PRIMARY KEY, state TEXT NOT NULL, city_code TEXT NOT NULL, city TEXT NOT NULL,
 source_code TEXT NOT NULL, name TEXT NOT NULL, geometry JSONB NOT NULL, source_hash TEXT NOT NULL,
 UNIQUE(state, city_code, source_code)
);
CREATE TABLE delivery_partitions (
 id UUID PRIMARY KEY, store_id UUID NOT NULL REFERENCES stores(id) ON DELETE RESTRICT,
 neighborhood_id UUID NOT NULL REFERENCES neighborhood_references(id) ON DELETE RESTRICT,
 active_revision INTEGER NOT NULL DEFAULT 1,
 UNIQUE(store_id, neighborhood_id), UNIQUE(id, store_id)
);
CREATE TABLE delivery_partition_revisions (
 id UUID PRIMARY KEY, partition_id UUID NOT NULL, store_id UUID NOT NULL,
 revision INTEGER NOT NULL, source_hash TEXT NOT NULL, cuts JSONB NOT NULL,
 request_id UUID NOT NULL, request_hash TEXT NOT NULL, author_id TEXT NOT NULL,
 created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(partition_id, store_id) REFERENCES delivery_partitions(id, store_id) ON DELETE RESTRICT,
 UNIQUE(partition_id, revision), UNIQUE(store_id, request_id), UNIQUE(id, store_id)
);
CREATE TABLE delivery_areas (
 id UUID PRIMARY KEY, revision_id UUID NOT NULL, store_id UUID NOT NULL,
 "index" INTEGER NOT NULL, name TEXT NOT NULL, geometry JSONB NOT NULL, inherited_from JSONB NOT NULL,
 FOREIGN KEY(revision_id, store_id) REFERENCES delivery_partition_revisions(id, store_id) ON DELETE RESTRICT,
 UNIQUE(revision_id, "index"), UNIQUE(id, store_id)
);
ALTER TABLE store_neighborhood_shipping ADD COLUMN area_id UUID;
CREATE UNIQUE INDEX store_neighborhood_shipping_area_id_key ON store_neighborhood_shipping(area_id);
CREATE UNIQUE INDEX store_neighborhood_shipping_area_id_store_id_key ON store_neighborhood_shipping(area_id,store_id);
ALTER TABLE store_neighborhood_shipping ADD CONSTRAINT store_neighborhood_shipping_area_store_fk
 FOREIGN KEY(area_id, store_id) REFERENCES delivery_areas(id, store_id) ON DELETE RESTRICT;
DROP INDEX store_neighborhood_shipping_store_id_neighborhood_key;
CREATE UNIQUE INDEX store_neighborhood_shipping_legacy_key ON store_neighborhood_shipping(store_id, neighborhood) WHERE area_id IS NULL;
ALTER TABLE "Order" ADD COLUMN delivery_area_id UUID REFERENCES delivery_areas(id) ON DELETE RESTRICT;
ALTER TABLE "Order" ADD COLUMN delivery_area_snapshot JSONB;

-- Shipping catalog is readable for spatial quotes; writes remain staff/store scoped.
CREATE FUNCTION app_shipping_store_write(target UUID) RETURNS BOOLEAN LANGUAGE sql STABLE AS $$
 SELECT COALESCE(current_setting('app.kind', true) = 'system', false)
 OR COALESCE(current_setting('app.role', true) = 'SUPER_ADMIN', false)
 OR (app_security_staff() AND EXISTS (
   SELECT 1 FROM stores s WHERE s.id = target AND
   (s.owner_id = app_security_user() OR EXISTS (SELECT 1 FROM "_UserStores" us WHERE us."A" = s.id AND us."B" = app_security_user()))
 ))
$$;
ALTER TABLE neighborhood_references ENABLE ROW LEVEL SECURITY;
ALTER TABLE neighborhood_references FORCE ROW LEVEL SECURITY;
CREATE POLICY catalog_read ON neighborhood_references FOR SELECT TO delivery_app USING (true);
DO $$ DECLARE t TEXT; BEGIN
 FOREACH t IN ARRAY ARRAY['delivery_partitions','delivery_partition_revisions','delivery_areas'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
  EXECUTE format('CREATE POLICY shipping_read ON %I FOR SELECT TO delivery_app USING (true)', t);
  EXECUTE format('CREATE POLICY shipping_insert ON %I FOR INSERT TO delivery_app WITH CHECK (app_shipping_store_write(store_id))', t);
  EXECUTE format('CREATE POLICY shipping_update ON %I FOR UPDATE TO delivery_app USING (app_shipping_store_write(store_id)) WITH CHECK (app_shipping_store_write(store_id))', t);
 END LOOP;
END $$;

GRANT SELECT ON neighborhood_references TO delivery_app;
GRANT SELECT, INSERT, UPDATE ON delivery_partitions, delivery_partition_revisions, delivery_areas TO delivery_app;
